mapper.select:
SELECT STR_TO_DATE( DATE_FORMAT( DATE_ADD( tx.occurred_at, INTERVAL 9 HOUR ), '%Y-%m-01' ), '%Y-%m-%d' ) AS report_month, COALESCE(SUM(tx.amount), 0) AS expense_amount FROM account_transaction tx INNER JOIN financial_account fa ON fa.financial_account_id = tx.financial_account_id WHERE fa.child_id = #{childId} AND fa.owner_type = 'CHILD' AND fa.account_product_type = 'DEMAND_DEPOSIT' AND tx.direction = 'DEBIT' AND tx.occurred_at >= #{startOccurredAt} AND tx.occurred_at < #{endOccurredAtExclusive}
AND NOT EXISTS ( SELECT 1 FROM financial_account destination WHERE destination.financial_account_id = tx.counterparty_account_id AND destination.child_id = #{childId} )
GROUP BY report_month ORDER BY report_month ASC
